<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; class ApiResponse { public function __construct(public int $status, public ?array $body, public bool $revoked = false) { } public function ok(): bool { return $this->status >= 200 && $this->status < 300; } public function attributes(): array { return (array) ($this->body['attributes'] ?? []); } public function items(): array { return array_values(array_filter(array_map( fn (mixed $row) => is_array($row) ? ($row['attributes'] ?? $row) : null, (array) ($this->body['data'] ?? []), ))); } public function meta(string $key, mixed $default = null): mixed { return data_get($this->body, 'meta.' . $key, $default); } public function error(): string { $detail = trim((string) data_get($this->body, 'errors.0.detail', '')); if ($this->status === 429) { return 'That is too many requests in a short time. Give it a minute and try again.'; } if ($this->status === 403) { return $detail !== '' && !str_contains(strtolower($detail), 'this action is unauthorized') ? $detail : 'Your account is not allowed to do that on this server.'; } if ($this->status === 404) { return 'That server could not be found, or your account cannot see it.'; } if ($this->status >= 500 && $detail === '') { return 'The panel could not finish that. The server\'s node may be unreachable right now.'; } return $detail !== '' ? $detail : 'The panel answered with HTTP ' . $this->status . '.'; } } 